import{PublicReturn}from"../common/public-return.js";import{getMd5}from"../common/crypto-tools.js";function generateClientId(e){const t=e.headers,n=t["user-agent"]||"",r=t["accept-encoding"]||"",i=t["accept-language"]||"",o=e.ip;return getMd5(`${o}-${n}-${r}-${i}`)}const requestMapList=[];export function getReqLimiter(e,t){const n=new Map;return requestMapList.push(n),async function(r,i){const o=generateClientId(r),s=(new Date).getTime();let c=n.get(o);if(c||(c={windowMs:t,maxRequests:e,startTime:s,number:0},n.set(o,c)),s-c.startTime<=t?c.number++:(c.startTime=s,c.number=1),c.number>e){let e=c.startTime+t-s;return e=(e/1e3).toFixed(3),void i.code(429).send(new PublicReturn(429,`请求过于频繁，请 ${e} s后再试`))}}}export function verifyOverTime(){const e=(new Date).getTime();requestMapList.forEach(t=>{t.forEach((n,r)=>{n.startTime+n.windowMs<=e||t.delete(r)})})}